head.script:
scwin.setVal = function() {
    if (WebSquare.wUnit.getJq('#trigger1').length == 0)
        WebSquare.wUnit.getObjById('wframe1_trigger1').click()
    else
        WebSquare.wUnit.getDomById('trigger1').click()
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 한다.wframe_submission_WPF-1252_(WSQ-1364).xml
    //1. Run the sample file.wframe_submission_WPF-1252_ (WSQ-1364) .xml
    //Verify step 1. "a" is displayed in the notification window, and then test a.xml is displayed.
    WebSquare.wUnit.addCommand("assert", "window.log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 08-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
